// No inputs; simple version query for coverage
unsigned long v = http_parser_version();
// Decode components to exercise bit math paths
unsigned int major = (unsigned int)((v >> 16) & 0xFF);
unsigned int minor = (unsigned int)((v >> 8) & 0xFF);
unsigned int patch = (unsigned int)(v & 0xFF);
// Basic sanity assertions about semantic version fields (non-negative and within byte range)
FUZZ_ASSERT(major <= 255 && minor <= 255 && patch <= 255, "version fields out of range");
// Validation: Trivially safe, no inputs or outputs. Covered version extraction logic.

// Enforce writable parser pointer (runtime guarantees non-null). Choose a valid parser type.
unsigned int t = *FUZZ_PARAM(unsigned int) % 3; // 0..2 maps to HTTP_REQUEST/HTTP_RESPONSE/HTTP_BOTH
enum http_parser_type type = (enum http_parser_type)t;

// Initialize the parser
http_parser_init(parser, type);

// Track initialization and type for later stubs
FUZZ_SET_ATTR_INT(parser, "initialized", 1);
FUZZ_SET_ATTR_INT(parser, "type", (int)t);
FUZZ_SET_ATTR_INT(parser, "executed", 0);
FUZZ_SET_ATTR_INT(parser, "headers_complete", 0);
FUZZ_SET_ATTR_INT(parser, "message_complete", 0);
// Validation: Parser is initialized with a valid type; attributes recorded for downstream checks.

// Initialize settings to zeroed callbacks as required by API
http_parser_settings_init(settings);
// Mark as initialized; callbacks may be configured by other stubs prior to execute
FUZZ_SET_ATTR_INT(settings, "initialized", 1);
FUZZ_SET_ATTR_INT(settings, "callbacks_set", 0);
// Validation: Safe zero-init; settings returned for reuse/configuration.

// Ensure parser was initialized
if (FUZZ_GET_ATTR_INT(parser, "initialized") != 1) { FUZZ_BAIL(); }
// Ensure settings are initialized; if not, initialize them here to be safe per API
if (FUZZ_GET_ATTR_INT(settings, "initialized") != 1) {
  http_parser_settings_init(settings);
  FUZZ_SET_ATTR_INT(settings, "initialized", 1);
  FUZZ_SET_ATTR_INT(settings, "callbacks_set", 0);
}

// If callbacks not yet set, install minimal non-capturing callbacks to exercise event paths
if (FUZZ_GET_ATTR_INT(settings, "callbacks_set") == 0) {
  settings->on_message_begin = +[](http_parser* p) -> int {
    FUZZ_SET_ATTR_INT(p, "in_message", 1);
    return 0; // continue
  };
  settings->on_url = +[](http_parser* p, const char* at, size_t length) -> int {
    (void)at; (void)length; // exercise callback path without heavy work
    return 0;
  };
  settings->on_status = +[](http_parser* p, const char* at, size_t length) -> int {
    (void)p; (void)at; (void)length; return 0;
  };
  settings->on_header_field = +[](http_parser* p, const char* at, size_t length) -> int {
    (void)p; (void)at; (void)length; return 0;
  };
  settings->on_header_value = +[](http_parser* p, const char* at, size_t length) -> int {
    (void)p; (void)at; (void)length; return 0;
  };
  settings->on_headers_complete = +[](http_parser* p) -> int {
    // Mark that headers were reached; return 0 to indicate continue with normal semantics
    FUZZ_SET_ATTR_INT(p, "headers_complete", 1);
    return 0;
  };
  settings->on_body = +[](http_parser* p, const char* at, size_t length) -> int {
    (void)p; (void)at; (void)length; return 0;
  };
  settings->on_message_complete = +[](http_parser* p) -> int {
    FUZZ_SET_ATTR_INT(p, "message_complete", 1);
    FUZZ_SET_ATTR_INT(p, "in_message", 0);
    return 0;
  };
  settings->on_chunk_header = +[](http_parser* p) -> int { (void)p; return 0; };
  settings->on_chunk_complete = +[](http_parser* p) -> int { (void)p; return 0; };
  FUZZ_SET_ATTR_INT(settings, "callbacks_set", 1);
}

// Prepare input buffer
std::string buf = FUZZ_PARAM_STR();
size_t max_len = buf.size();
// Choose a length within the buffer bounds
size_t len = (max_len == 0) ? 0 : (*FUZZ_PARAM(unsigned int) % (max_len + 1));
// Exercise API allowance: data may be NULL iff len == 0
const char* data_ptr = (len == 0 && ((*FUZZ_PARAM(unsigned int) % 2) == 0)) ? nullptr : buf.data();

size_t nparsed = http_parser_execute(parser, settings, data_ptr, len);
// Property: parser must not claim to have parsed more than len bytes
FUZZ_ASSERT(nparsed <= len, "nparsed exceeds input length");

// Record that execute ran at least once
FUZZ_SET_ATTR_INT(parser, "executed", 1);
// Validation: Ensures parser/settings are properly initialized, installs safe callbacks, and checks basic postconditions.

// Require that the parser has at least reached headers to make this meaningful
if (FUZZ_GET_ATTR_INT(parser, "headers_complete") == 0 && FUZZ_GET_ATTR_INT(parser, "message_complete") == 0) {
  FUZZ_BAIL();
}
int ka = http_should_keep_alive(parser);
(void)ka; // Value is advisory; just exercising the path
// Validation: Only called after headers/message completion as tracked via attributes.

// Derive a valid enum http_method from a previously used parser (requests only)
if (FUZZ_GET_ATTR_INT(parser, "executed") != 1) { FUZZ_BAIL(); }
// If parser is not in request mode, result may be unspecified; enforce request or both
int ptype = FUZZ_GET_ATTR_INT(parser, "type");
if (!(ptype == 0 /*HTTP_REQUEST*/ || ptype == 2 /*HTTP_BOTH*/)) { FUZZ_BAIL(); }
// Use the parser's method field which the library sets during parsing
enum http_method m = (enum http_method)parser->method;
const char* name = http_method_str(m);
(void)name;
// Validation: Uses library-provided method value to avoid out-of-range enums.

// Derive a valid enum http_status from a previously used parser (responses only)
if (FUZZ_GET_ATTR_INT(parser, "executed") != 1) { FUZZ_BAIL(); }
int ptype = FUZZ_GET_ATTR_INT(parser, "type");
if (!(ptype == 1 /*HTTP_RESPONSE*/ || ptype == 2 /*HTTP_BOTH*/)) { FUZZ_BAIL(); }
// Use parser's status_code which is a 16-bit field in the struct
enum http_status s = (enum http_status)parser->status_code;
const char* reason = http_status_str(s);
(void)reason;
// Validation: Avoids guessing status values by sourcing from the parser state.

// Use current parser error code as a valid enum http_errno
if (FUZZ_GET_ATTR_INT(parser, "executed") != 1) { FUZZ_BAIL(); }
enum http_errno err = (enum http_errno)parser->http_errno;
const char* n = http_errno_name(err);
(void)n;
// Validation: Calls with a library-generated error code, avoiding undefined ranges.

// Use current parser error code as a valid enum http_errno
if (FUZZ_GET_ATTR_INT(parser, "executed") != 1) { FUZZ_BAIL(); }
enum http_errno err = (enum http_errno)parser->http_errno;
const char* d = http_errno_description(err);
(void)d;
// Validation: Same safety as errno_name; ensures valid enum values.

// Pause or unpause based on fuzzed bit
int paused = (int)(*FUZZ_PARAM(unsigned int) & 1u);
http_parser_pause(parser, paused);
// Record paused state to help future logic (optional)
FUZZ_SET_ATTR_INT(parser, "paused", paused);
// Validation: Simple state toggle; parser returned for continued use.

// Meaningful primarily during/after body parsing; require at least an execute
if (FUZZ_GET_ATTR_INT(parser, "executed") != 1) { FUZZ_BAIL(); }
int fin = http_body_is_final(parser);
(void)fin;
// Validation: Called only on a parser that has processed data.

// Set a global/process-wide header size limit. Keep within a small bound for fuzzer performance.
uint32_t size = (uint32_t)(*FUZZ_PARAM(unsigned int) % 2048u);
http_parser_set_max_header_size(size);
// Track globally for potential diagnostics
FUZZ_SET_ATTR_INT_GLOBAL("max_header_size", (int)size);
// Validation: Safe global setter with bounded value for performance.

// Zero-initialize the URL parser result struct per API
http_parser_url_init(u);
// Track init for downstream parse_url
FUZZ_SET_ATTR_INT(u, "initialized", 1);
FUZZ_SET_ATTR_INT(u, "url_parsed", 0);
// Validation: Safe zero-init of caller-owned storage; returns u for reuse.

// Ensure the result struct is initialized (avoid stale data)
if (FUZZ_GET_ATTR_INT(u, "initialized") != 1) {
  http_parser_url_init(u);
  FUZZ_SET_ATTR_INT(u, "initialized", 1);
  FUZZ_SET_ATTR_INT(u, "url_parsed", 0);
}
// Generate candidate URL buffer (may contain NULs); truncate length for performance
std::string s = FUZZ_PARAM_STR();
size_t max_len = s.size();
size_t cap = max_len < 1024 ? max_len : (size_t)1024; // cap work per call
size_t buflen = (cap == 0) ? 0 : (*FUZZ_PARAM(unsigned int) % (cap + 1));
// Choose CONNECT authority-form flag randomly
int is_connect = (int)(*FUZZ_PARAM(unsigned int) & 1u);
// Parse; buffer does not need to be NUL-terminated and may include NULs
int rc = http_parser_parse_url(s.data(), buflen, is_connect, u);
// Mark success/failure in attributes for later consumers
FUZZ_SET_ATTR_INT(u, "url_parsed", rc == 0 ? 1 : 0);
FUZZ_SET_ATTR_INT(u, "is_connect", is_connect);
// Validation: Initializes as needed, respects exact-length semantics, and records parse result for downstream checks.

// Allocate settings and initialize via API, ensuring non-null output
http_parser_settings *settings = new (std::nothrow) http_parser_settings();
if (!settings) { FUZZ_BAIL(); }
http_parser_settings_init(settings);

// Optionally install some callbacks to broaden coverage; use no-capture lambdas so they decay to C function pointers
unsigned int mask = *FUZZ_PARAM(unsigned int);
int callbacks_installed = 0;
if (mask & 1u) { settings->on_message_begin = +[](http_parser* p) -> int { FUZZ_SET_ATTR_INT(p, "in_message", 1); return 0; }; callbacks_installed = 1; }
if (mask & 2u) { settings->on_url = +[](http_parser* p, const char* at, size_t len) -> int { (void)p; (void)at; (void)len; return 0; }; callbacks_installed = 1; }
if (mask & 4u) { settings->on_status = +[](http_parser* p, const char* at, size_t len) -> int { (void)p; (void)at; (void)len; return 0; }; callbacks_installed = 1; }
if (mask & 8u) { settings->on_header_field = +[](http_parser* p, const char* at, size_t len) -> int { (void)p; (void)at; (void)len; return 0; }; callbacks_installed = 1; }
if (mask & 16u) { settings->on_header_value = +[](http_parser* p, const char* at, size_t len) -> int { (void)p; (void)at; (void)len; return 0; }; callbacks_installed = 1; }
if (mask & 32u) { settings->on_headers_complete = +[](http_parser* p) -> int { FUZZ_SET_ATTR_INT(p, "headers_complete", 1); return 0; }; callbacks_installed = 1; }
if (mask & 64u) { settings->on_body = +[](http_parser* p, const char* at, size_t len) -> int { (void)p; (void)at; (void)len; return 0; }; callbacks_installed = 1; }
if (mask & 128u) { settings->on_message_complete = +[](http_parser* p) -> int { FUZZ_SET_ATTR_INT(p, "message_complete", 1); FUZZ_SET_ATTR_INT(p, "in_message", 0); return 0; }; callbacks_installed = 1; }
if (mask & 256u) { settings->on_chunk_header = +[](http_parser* p) -> int { (void)p; return 0; }; callbacks_installed = 1; }
if (mask & 512u) { settings->on_chunk_complete = +[](http_parser* p) -> int { (void)p; return 0; }; callbacks_installed = 1; }

// Track initialization and whether callbacks were set for downstream stubs
FUZZ_SET_ATTR_INT(settings, "initialized", 1);
FUZZ_SET_ATTR_INT(settings, "callbacks_set", callbacks_installed);

// Validation: Ensures non-null allocated settings, zero-inits per API, and safely installs optional callbacks.

// Allocate URL result object and initialize per API
struct http_parser_url *u = new (std::nothrow) http_parser_url();
if (!u) { FUZZ_BAIL(); }
http_parser_url_init(u);

// Attribute tracking for downstream parse_url usage
FUZZ_SET_ATTR_INT(u, "initialized", 1);
FUZZ_SET_ATTR_INT(u, "url_parsed", 0);

// Validation: Provides a fresh, zero-initialized http_parser_url suitable for parsing.

// Allocate parser storage and initialize with a valid type
http_parser *parser = new (std::nothrow) http_parser();
if (!parser) { FUZZ_BAIL(); }
unsigned int t = *FUZZ_PARAM(unsigned int) % 3; // HTTP_REQUEST=0, HTTP_RESPONSE=1, HTTP_BOTH=2
enum http_parser_type type = (enum http_parser_type)t;
http_parser_init(parser, type);

// Record lifecycle and mode attributes for downstream API usage
FUZZ_SET_ATTR_INT(parser, "initialized", 1);
FUZZ_SET_ATTR_INT(parser, "type", (int)t);
FUZZ_SET_ATTR_INT(parser, "executed", 0);
FUZZ_SET_ATTR_INT(parser, "headers_complete", 0);
FUZZ_SET_ATTR_INT(parser, "message_complete", 0);
FUZZ_SET_ATTR_INT(parser, "paused", 0);

// Validation: Allocates and properly initializes an http_parser, annotating state for subsequent stubs.

