import random
import string
from typing import List, Tuple

# URL generator for http_parser_parse_url fuzzer
# Produces valid and diverse URL byte sequences (not NUL-terminated) up to 1024 bytes
# Seeded randomness for reproducibility.

SAFE_PCHAR = string.ascii_letters + string.digits + "-._~"
SUBDELIMS = "!$&'()*+,;="
UNRESERVED = SAFE_PCHAR
PCHAR_SAFE = UNRESERVED + SUBDELIMS + ":@"  # pchar without pct-encoded (we add %XX separately)
HEX = "0123456789ABCDEF"

SCHEMES = [
    "http", "https", "ws", "wss", "ftp", "file", "gopher", "mailto", "urn"
]
USERINFO_SPECIAL = ":;=+$,"
HOST_LABEL_CHARS = string.ascii_letters + string.digits + "-"
PATH_SEGMENT_SPECIAL = ";@"  # allowed in pchar
QUERY_FRAGMENT_EXTRA = "/?"

COMMON_PATHS = [
    "/", "/index.html", "/api/v1/resource", "/a/b/c", "/%s/%s",
    "/search", "/robots.txt", "/.well-known/security.txt"
]

COMMON_QUERIES = [
    "q=parser", "a=1&b=2", "x=%s", "token=abc123", "empty=", "arr=1&arr=2",
]

COMMON_FRAGMENTS = ["top", "section-1", "⚑", "frag", "line=10"]

PORTS = ["", ":80", ":443", ":8080", ":65535", ":1"]


def rand_pct_encoded(r: random.Random) -> str:
    b = r.randrange(0, 256)
    return "%" + HEX[(b >> 4) & 0xF] + HEX[b & 0xF]


def rand_label(r: random.Random, min_len=1, max_len=10) -> str:
    # DNS label: start/end alnum, may contain '-'
    n = r.randint(min_len, max_len)
    if n == 1:
        return r.choice(string.ascii_lowercase + string.digits)
    s = [r.choice(string.ascii_lowercase + string.digits)]
    for _ in range(n - 2):
        s.append(r.choice(HOST_LABEL_CHARS))
    s.append(r.choice(string.ascii_lowercase + string.digits))
    return "".join(s)


def rand_host(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.15:
        # IPv4
        return ".".join(str(r.randint(0, 255)) for _ in range(4))
    if choice < 0.25:
        # Simple bracketed IPv6 samples
        return r.choice(["[::1]", "[2001:db8::1]", "[::ffff:192.0.2.1]"])
    # Domain with 1-4 labels, optionally punycode-like token
    labels = [rand_label(r) for _ in range(r.randint(1, 4))]
    if r.random() < 0.2:
        labels[-1] = "xn--" + rand_label(r, 3, 8)
    return ".".join(labels)


def rand_userinfo(r: random.Random) -> str:
    if r.random() < 0.6:
        user = ''.join(r.choice(SAFE_PCHAR + USERINFO_SPECIAL) for _ in range(r.randint(1, 8)))
        if r.random() < 0.7:
            pwd = ''.join(r.choice(SAFE_PCHAR + USERINFO_SPECIAL) for _ in range(r.randint(0, 6)))
            return f"{user}:{pwd}@"
        return user + "@"
    return ""


def rand_port(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(PORTS)
    return ":" + str(r.randint(1, 65535))


def rand_pct_or_char(r: random.Random, extra: str = "") -> str:
    if r.random() < 0.15:
        return rand_pct_encoded(r)
    return r.choice(PCHAR_SAFE + extra)


def rand_segment(r: random.Random, min_len=0, max_len=12) -> str:
    n = r.randint(min_len, max_len)
    return ''.join(rand_pct_or_char(r, PATH_SEGMENT_SPECIAL) for _ in range(n))


def _choose_common_path(r: random.Random) -> str:
    # Pick a template once and use consistently to avoid mismatched formatting
    tmpl = r.choice(COMMON_PATHS)
    if "%s" in tmpl:
        return tmpl % (rand_label(r), rand_label(r))
    return tmpl


def rand_path(r: random.Random) -> str:
    if r.random() < 0.4:
        return _choose_common_path(r)
    depth = r.randint(0, 6)
    segs = [rand_segment(r) for _ in range(depth)]
    return "/" + "/".join(segs) if segs else "/"


def rand_query(r: random.Random) -> str:
    if r.random() < 0.5:
        base = r.choice(COMMON_QUERIES)
        if "%s" in base:
            base = base % (rand_pct_or_char(r))
        return "?" + base
    # Build k=v pairs
    pairs = []
    for _ in range(r.randint(1, 4)):
        k = ''.join(r.choice(UNRESERVED) for _ in range(r.randint(1, 6)))
        v_len = r.randint(0, 8)
        v = ''.join(rand_pct_or_char(r, QUERY_FRAGMENT_EXTRA) for _ in range(v_len))
        pairs.append(f"{k}={v}")
    s = "&".join(pairs)
    return "?" + s


def rand_fragment(r: random.Random) -> str:
    if r.random() < 0.5:
        return "#" + r.choice(COMMON_FRAGMENTS)
    n = r.randint(1, 12)
    s = ''.join(rand_pct_or_char(r, QUERY_FRAGMENT_EXTRA) for _ in range(n))
    return "#" + s


def build_absolute_uri(r: random.Random) -> str:
    scheme = r.choice(SCHEMES)
    auth = "//" + rand_userinfo(r) + rand_host(r) + rand_port(r)
    path = rand_path(r)
    q = rand_query(r) if r.random() < 0.7 else ""
    f = rand_fragment(r) if r.random() < 0.4 else ""
    return f"{scheme}:{auth}{path}{q}{f}"


def build_authority_form(r: random.Random) -> str:
    # For CONNECT: authority form host[:port]
    return rand_host(r) + (rand_port(r) if r.random() < 0.9 else "")


def build_origin_form(r: random.Random) -> str:
    # Typical request-target in Request-Line without scheme/authority
    path = rand_path(r)
    q = rand_query(r) if r.random() < 0.6 else ""
    f = rand_fragment(r) if r.random() < 0.3 else ""
    return f"{path}{q}{f}"


def build_asterisk_form() -> str:
    return "*"


def build_relative_ref(r: random.Random) -> str:
    # e.g., ./a/../b?x#y
    parts = []
    if r.random() < 0.6:
        parts.append("./")
    if r.random() < 0.4:
        parts.append("../")
    parts.append(rand_path(r))
    if r.random() < 0.5:
        parts.append(rand_query(r))
    if r.random() < 0.3:
        parts.append(rand_fragment(r))
    return ''.join(parts)


def maybe_embed_nuls(r: random.Random, s: bytes) -> bytes:
    # http_parser_parse_url accepts NULs; fuzzers pass explicit length.
    if not s:
        return s
    if r.random() < 0.15:
        # Insert a small number of NULs at random positions
        b = bytearray(s)
        for _ in range(r.randint(1, 3)):
            pos = r.randrange(0, len(b))
            b.insert(pos, 0)
        return bytes(b)
    return s


def clamp_size(b: bytes, max_len: int = 1024) -> bytes:
    return b[:max_len]


def build_url_bytes(r: random.Random) -> bytes:
    pick = r.random()
    if pick < 0.30:
        s = build_absolute_uri(r)
    elif pick < 0.45:
        s = build_authority_form(r)
    elif pick < 0.85:
        s = build_origin_form(r)
    elif pick < 0.95:
        s = build_relative_ref(r)
    else:
        s = build_asterisk_form()

    # Occasionally produce upper-case scheme or mixed case paths to test case-insensitivity where applicable
    if r.random() < 0.2 and ":" in s:
        scheme, rest = s.split(":", 1)
        scheme = scheme.upper() if r.random() < 0.5 else scheme.capitalize()
        s = scheme + ":" + rest

    # Encode to bytes (utf-8), keep non-ASCII fragments as UTF-8 which many clients emit
    b = s.encode('utf-8', errors='strict')

    # Occasionally add trailing spaces or tabs which are technically not part of URL but parser takes exact len
    if r.random() < 0.1:
        tail = r.choice(["", " ", "\t"]) * r.randint(1, 3)
        b += tail.encode('ascii')

    b = maybe_embed_nuls(r, b)
    b = clamp_size(b)
    return b


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Mix additional entropy so same seed across runs still gives variety per call site
    for _ in range(3):
        r.random()
    return build_url_bytes(r)
